const DollLayers={
 columns:[0,166,324,482,640,796,952,1108,1254],
 maleHair:['蓬松中分','柔软碎刘海','侧分微卷','轻盈八字刘海','凌乱短卷','露额蓬松发','侧掠层次发','圆润层次短发'],
 femaleHair:['缎带双马尾','贝雷帽长卷发','高马尾','蓬松低双髻','双麻花辫','低双马尾','发箍长直发','发夹短波波'],
 expressions:['平静','温柔微笑','开心','小小生气','惊讶','害羞'],
 clothes:['男生街头外套','男生学院开衫','男生运动套装','男生兔子卫衣','女生街头套装','女生学院套装','女生运动套装','女生兔子裙'],
 defaults(id){const previous=living.avatars[id]||{},male=previous.cut==='suit'||id!=='me'&&roles.findIndex(r=>r.id===id)%2===1,index=referenceIndex(id,previous);return {body:male?0:1,hair:male?0:8,expression:0,clothing:index,tone:'natural',...previous.mix}},
 valid(a){return a&&[0,1].includes(a.body)&&Number.isInteger(a.hair)&&a.hair>=0&&a.hair<16&&Number.isInteger(a.expression)&&a.expression>=0&&a.expression<6&&Number.isInteger(a.clothing)&&a.clothing>=0&&a.clothing<8&&['natural','black','silver','rose'].includes(a.tone)},
 rect(row,col){const inset=row===1?8:0;return [this.columns[col]+inset,row===1?474:row===2?704:row===3?974:194,this.columns[col+1]-this.columns[col]-inset*2,row===1?182:row===2?258:row===3?262:84]},
 svg(rect,target,clip=''){const [sx,sy,sw,sh]=rect,[x,y,w,h]=target,key='layer'+crypto.randomUUID().replace(/-/g,'');return `<svg class="doll-part" style="width:${w}px;height:${h}px" x="${x}" y="${y}" width="${w}" height="${h}" viewBox="${sx} ${sy} ${sw} ${sh}" preserveAspectRatio="none" overflow="hidden"><defs><clipPath id="${key}"><rect x="${sx}" y="${sy}" width="${sw}" height="${sh}"/></clipPath></defs><g clip-path="url(#${key})"><image href="assets/character-layers-v15.webp" width="1254" height="1254"/></g></svg>`},
 render(a){const male=a.hair<8,hair=this.rect(male?1:2,a.hair%8),hairTarget=male?[9,17,182,183]:[0,18,200,285],base=a.body===0?[5,86,153,350]:[168,86,148,350],filter={natural:'none',black:'brightness(.65) saturate(.6)',silver:'grayscale(1) brightness(1.6)',rose:'sepia(.25) hue-rotate(285deg) saturate(.7) brightness(1.15)'}[a.tone],mask='dollFace'+crypto.randomUUID().replace(/-/g,'');return `<span class="chibi layered-character" role="img" aria-label="自由搭配：${a.hair<8?this.maleHair[a.hair]:this.femaleHair[a.hair-8]}、${this.expressions[a.expression]}、${this.clothes[a.clothing]}"><svg viewBox="0 0 200 410" xmlns="http://www.w3.org/2000/svg"><g class="doll-hair-layer" style="filter:${filter}">${this.svg(hair,hairTarget)}</g>${this.svg(base,[23,38,154,350])}${this.svg(this.rect(3,a.clothing),[8,180,184,208])}${this.svg(this.rect(0,a.expression+2),[49,124,102,42])}<defs><mask id="${mask}"><rect width="200" height="200" fill="white"/>${a.hair===7?'<ellipse cx="100" cy="147" rx="58" ry="36" fill="black"/>':''}</mask></defs><svg style="width:200px;height:188px" width="200" height="188" overflow="hidden"><g mask="url(#${mask})" style="filter:${filter}">${this.svg(hair,hairTarget)}</g></svg></svg></span>`}
};
const referenceAvatarRenderer=chibiAvatar;
chibiAvatar=function(id='me',draft=null){const a=draft||living.avatars[id]||{},uploaded=!draft&&mediaCache.get('chibi:'+id);if(uploaded)return referenceAvatarRenderer(id);return a.layered&&DollLayers.valid(a.mix)?DollLayers.render(a.mix):referenceAvatarRenderer(id,draft)};
const referenceOutfitEditor=openChibiEditor;
openChibiEditor=function(id='me'){let mix=DollLayers.defaults(id);const draw=()=>{const key=['rose','mint','lilac','gold'][mix.clothing%4],owned=homeland.owned.includes(key),price=PalaisHome.clothes[key].price;const choices=(label,field,items,offset=0)=>`<h3>${label}</h3><div class="doll-layer-choices">${items.map((name,i)=>`<button data-layer-field="${field}" data-layer-index="${i+offset}" aria-pressed="${mix[field]===i+offset}">${DollLayers.render({...mix,[field]:i+offset})}<small>${name}</small></button>`).join('')}</div>`;const d=homePanel(`<div class="eyebrow">MIX YOUR OWN LITTLE PERSON</div><h2>${id==='me'?'我':escapeHtml(roles.find(r=>r.id===id)?.name||'角色')} · 自由搭配</h2><div class="living-preview" id="chibiLive">${DollLayers.render(mix)}</div><p class="daily-caption">发型、表情和衣服是独立图层，选哪个就组合哪个。每位角色单独保存；预览免费，未拥有的衣服确认后才付钱。</p><button class="text-button" id="backFullOutfit">查看原图成套造型 ↗</button><div class="chibi-choices"><button data-layer-field="body" data-layer-index="0">男生基础体型</button><button data-layer-field="body" data-layer-index="1">女生基础体型</button></div>${choices('男生发型','hair',DollLayers.maleHair)}${choices('女生发型','hair',DollLayers.femaleHair,8)}<h3>发色色调（只改变头发）</h3><div class="chibi-choices">${[['natural','原色'],['black','深黑'],['silver','银灰'],['rose','雾玫瑰']].map(([v,n])=>`<button data-hair-tone="${v}" aria-pressed="${mix.tone===v}">${n}</button>`).join('')}</div>${choices('表情','expression',DollLayers.expressions)}${choices('服装','clothing',DollLayers.clothes)}<p class="daily-caption">零钱 ¥${PalaisWallet.money(wallet.balance)} · 当前服装${owned?'已拥有':' ¥'+PalaisWallet.money(price*100)}</p><div class="actions"><button class="secondary" id="uploadLayeredFigure">上传完整形象</button><button class="primary" id="saveLayeredFigure">${owned?'保存搭配':'购买并保存 · ¥'+PalaisWallet.money(price*100)}</button></div><input type="file" hidden id="layeredFigureFile" accept="image/png,image/jpeg,image/webp">`);d.querySelectorAll('[data-layer-field]').forEach(b=>b.onclick=()=>{mix[b.dataset.layerField]=Number(b.dataset.layerIndex);draw()});d.querySelectorAll('[data-hair-tone]').forEach(b=>b.onclick=()=>{mix.tone=b.dataset.hairTone;draw()});$('#backFullOutfit').onclick=()=>referenceOutfitEditor(id);$('#uploadLayeredFigure').onclick=()=>$('#layeredFigureFile').click();$('#layeredFigureFile').onchange=async e=>{try{await mediaWrite('chibi:'+id,await prepareImage(e.target.files[0],1000));d.close();renderHomeland();toast('完整形象已上传')}catch(e){toast(e.message)}};$('#saveLayeredFigure').onclick=async()=>{const b=$('#saveLayeredFigure');b.disabled=true;try{if(!DollLayers.valid(mix))throw Error('请选择有效的搭配');const chosen={...mix},purchaseKey=['rose','mint','lilac','gold'][chosen.clothing%4],result=PalaisHomeCash.purchaseStyle(wallet,homeland,purchaseKey,crypto.randomUUID(),Date.now(),PalaisHome.clothes),old=mediaCache.get('chibi:'+id)||null;await mediaWrite('chibi:'+id,null);try{livingCommit(result.wallet,{...living,avatars:{...living.avatars,[id]:{...living.avatars[id],layered:true,mix:chosen,outfit:purchaseKey}}},result.home)}catch(e){await mediaWrite('chibi:'+id,old).catch(()=>{});throw e}d.close();renderHomeland();toast('发型、表情与衣服的独立搭配已保存')}catch(e){toast(e.message);b.disabled=false}}};draw()};
